'use strict';
// Guide pages: Getting Started and Characters.
module.exports = (L) => {
  const { D, esc, nm, cap, num, writeImg, art, PORT, table, pill, h2, card, imgTag, emit, route, ROOM } = L;
  const K = D.K.CLASSES, SP = D.K.SPELLS, base = Object.keys(K).filter((k) => !K[k].remort), rem = Object.keys(K).filter((k) => K[k].remort);
  const ROLE = { magician: 'Burst caster', thief: 'Crits and poison', alchemist: 'Bombs and heals', gunslinger: 'Rapid fire', barbarian: 'Tank and brawler', engineer: 'Turrets and gadgets', necromancer: 'Drain and minions', cleric: 'Healer', druid: 'Nature and companions', bard: 'Support and crowd control', wirewalker: 'Net hacker', scavenger: 'Gatherer and crafter', dragon: 'Breath weapons', android: 'Precision and repair', shapeshifter: 'Beast forms' };
  const portraits = (k) => ['female', 'male', 'nonbinary'].map((g) => { return `<img src="../img/player/${k}-${g[0]}.jpg" alt="${esc(K[k].name)} ${g === 'nonbinary' ? 'other' : g}" loading="lazy">`; }).join('');

  // ---------------- how to play ----------------
  const step = (n, t, body) => `<div class="step"><div class="sn">${n}</div><div><h3>${t}</h3>${body}</div></div>`;
  emit('how-to-play', 'How to Play', 'MULTIVERSE MUD is a text world you play in your browser. Here is everything you need for your first ten minutes.', `
<div class="banner2">${imgTag('area-town.svg', 'Ashfall')}<p><b>Welcome to the junction.</b> MULTIVERSE MUD mixes fantasy realms, sci-fi worlds and Old West towns with saloons. Every road starts in Ashfall Junction, where portals from every world meet. </p></div>
<div class="steps">
${step(1, 'Create your character', '<p>Pick a name (3 to 12 letters), a password, a <a href="classes.html">class</a> and a gender (male, female or other). Your class decides your spells and your strengths. It can only change by <a href="remorting.html">remorting</a> at level 40. On a brand-new server the first account created becomes the wizard (administrator).</p>')}
${step(2, 'Look around', '<p>You begin in <b>Ashfall Square</b>, which is safe: nobody can fight here. Type <code>look</code> (or <code>l</code>) to see the room. The map in the right column already shows all of Ashfall, with a glowing <b>YOU</b> marker on your room. Move with <code>n</code> <code>s</code> <code>e</code> <code>w</code> <code>u</code> <code>d</code>, the compass buttons, or the <a href="interface.html">keypad</a>.</p>')}
${step(3, 'Heal, gear up, and stock up', `<p>North of the inn, the <b>Dawn Clinic</b> (Temple of the Dawn) heals you fully for free up to level 15: type <code>pray</code>. At <b>Brann's Smithy</b> (${route('town/smithy')} from the square) a free rack holds starter gear: <code>get all</code>, then <code>wear</code> and <code>wield</code> what you find. <b>Market Row</b> sells red stims and mana cells (<code>list</code>, <code>buy 2 potion</code>).</p>`)}
${step(4, 'Take your first contract', '<p>Visit the <b>Adventurers\' Guild</b> and type <code>board</code> to see open contracts. <code>talk torv</code> then <code>accept first</code> starts <i>First Steps</i>. The <b>quest window</b> (button or the <b>Q</b> key) lists every accepted contract with exactly what it needs. Turn a finished contract in by talking to whoever gave it.</p>')}
${step(5, 'Hunt your first monsters', '<p>Leave through the North Gate to the <a href="areas.html#forest">Whisperwood</a>. Rats and goblins are good first targets: <code>kill rat</code>. Cast spells by typing the spell name (<code>spark</code>) or <code>cast spark</code>; see <code>spells</code> for your list. Fights run automatically every two seconds. Watch your big HP bar: below half, drink a stim (<code>quaff</code>), or <code>flee</code>. Dying is not permanent: you lose 10% of your XP, wake in Ashfall, and an NPC taunts you in front of everyone.</p>')}
${step(6, 'Loot, sell, upgrade', '<p><code>get all</code> picks up drops. Gathered materials and looted gear flow into your <a href="tools-bag.html">Bag of Holding</a> automatically. At any shop <code>sell all</code> turns loot into credits (the <b>Salvage Exchange</b> pays most for materials). Spend credits on better <a href="gear.html">gear</a>, <a href="consumables.html">potions</a> and <a href="cyberware.html">cyberware</a>.</p>')}
${step(7, 'Level up and unlock', '<p>Each level raises your health and mana, and your class unlocks new <a href="spells.html">spells</a> at levels 1, 2, 4, 6, 8, 10, 15, 22, 30 and 40. Check the <a href="experience.html">experience table</a> to see what each level costs. New areas open up as you grow: see <a href="areas.html">Areas</a>.</p>')}
${step(8, 'Learn a tradeskill', '<p>Anyone can learn <a href="tradeskills.html">tradeskills</a> for free at any time: type <code>tradeskills</code>, then <code>learn mining</code>. Your bound <a href="tools-bag.html">tools</a> (fishing pole, mining pick and more) are already yours and improve with use.</p>')}
${step(9, 'Reach level 40 and remort', '<p>At level 40, go to the <b>Hall of Rebirth</b> and <code>remort</code> into a Dragon, Android, Shapeshifter, Gambler, Ripperdoc, Outlaw or Pirate with stronger skills. You can do it up to 40 times. <a href="remorting.html">Read the remort guide.</a></p>')}
</div>
${h2('Ten tips for new runners')}<ul class="tips"><li><b>drink fountain</b> in Ashfall Square restores all your health and mana, free. Come back to it whenever you are hurt.</li><li><b>recall</b> teleports you to the starting square any time you are not fighting.</li><li>Camps (marked <b>C</b> on the map) and the inn regenerate you faster. Safe rooms never have combat.</li><li>Always carry two healing stims.</li><li>A <code>look</code> at a monster shows its level and condition.</li><li>Luck saves you from one killing blow: it halves the damage automatically.</li><li>Prospectors are gatherers, not fighters. Stick to safe gathering spots.</li><li>Chrome costs Aura, and low Aura shrinks your mana pool.</li><li><code>score</code> shows XP to next level, vitals, wealth and materials.</li><li>The gossip channel (<code>/g hello</code>) reaches everyone online.</li><li>Bosses are tough. Bring stims, mana cells and friends.</li></ul>`);

  // ---------------- interface ----------------
  const KEYS = [['1', 'southwest'], ['2', 'south'], ['3', 'southeast'], ['4', 'west'], ['5', 'look'], ['6', 'east'], ['7', 'northwest'], ['8', 'north'], ['9', 'northeast'], ['0', 'get all'], ['.', 'heal (eat or drink your best healing item)'], ['+', 'down'], ['-', 'up'], ['*', 'out'], ['/', 'kill'], ['Enter', 'nothing until you assign it']];
  emit('interface', 'Interface and Controls', 'The browser client has three columns. Here is what everything does.', `
${h2('The three columns')}${table(['Column', 'What is in it'], [['Left', 'The gossip channel along the bottom, and above it your vitals (a big HP bar, XP and mana), the Quests button, weapon, armor and credits, Luck and Aura, the spellbook with clickable spells, the compass pad, and quick buttons (pack, score, flee, who).'], ['Centre', 'The game text, the gossip channel pane, and the command line. Up and Down arrows recall earlier commands.'], ['Right', 'The map, the combat view, and the portrait window.']])}
${h2('The map')}<p>The map shows every room you have explored, plus all of Ashfall from your first login. Rooms are drawn with their <b>terrain</b>: grass blades, dirt, stone slabs, concrete and riveted metal. Your room has a glowing frame, a <b>YOU</b> label and your class icon. A cyan dot marks another player, a red number counts monsters in your room, and ▲ ▼ mark stairs. Terrain legend sits under the map. See the <a href="map.html">full world map</a>.</p>
${h2('Combat view and portrait')}<p>When a fight starts you see both fighters, health bars, flying damage numbers, and a projectile for each spell. Under it, the <b>portrait window</b> shows the NPC you are talking to, or a generated portrait of you (class and gender) when there is no picture.</p>
${h2('Quest window')}<p>The Quests button (or the <b>Q</b> key) shows or hides the quest window, which sits at the <b>bottom of the left column, under the Player\'s Guide link</b>. It scrolls up and down when you have several quests, and holds <b>only your accepted quests</b>: who gave each, the quest text, every requirement with a progress bar, a READY TO TURN IN badge and where to hand it in, and the reward. It opens by itself the first time you accept a quest.</p><p>Clicking anywhere in the main text window puts the cursor on the command line, and any web address (http or https) in the text or in gossip is a link that opens in a new window. The interface now uses an <b>orange</b> accent (command line outline, quest window and settings gear).</p>
${h2('Settings (the gear button)')}<p>Choose the text <b>font</b> (serif, sans, monospace, typewriter, rounded, wide), the <b>size</b>, and switch <b>keypad controls</b> (on by default) on or off or re-map to any commands you like. A sound toggle sits under your vitals: level-up, contract and death jingles are original, public-domain (CC0) sounds.</p>
${h2('Keypad controls')}<p>They are on by default (you can turn them off in settings). Make sure Num Lock is on, and use these keys whenever the command line is empty:</p>${table(['Key', 'Does'], KEYS.map(([k, v]) => [`<kbd>${k}</kbd>`, v]))}<p>These are the defaults. In settings, open <b>Edit keypad keys</b> and type a command for any key, for example <code>look;score</code> (separate several commands with <code>;</code>). You can also type <code>keypad 5 look</code>, <code>keypad reset</code>, or <code>keypad on|off</code>. Your layout is saved to your character, so it follows you to any browser.</p>
${h2('Other shortcuts')}${table(['Keys', 'Does'], [['<kbd>Alt</kbd> + arrow keys', 'Walk north, south, west, east'], ['<kbd>Q</kbd>', 'Toggle the quest window'], ['<kbd>L</kbd>', 'Toggle the Top 10 achievements leaderboard window (draggable)'], ['Settings: Triggers', 'Add text patterns that run commands automatically, highlight lines, or both'], ['Settings: Show the newbie tutorial', 'Reopens the step-by-step dialog tour'], ['Settings: Gossip window', 'Make the gossip text bigger or smaller, and put the gossip window at the bottom of the left or right column'], ['Vitals bar and heal button', 'Just above the command line: your health, mana (stamina for Prospectors) and experience bars, and below them a quick-key bar that stretches the full width of the command line. The <b>heal</b> button sends <code>eat</code>, and there is room for more quick keys'], ['Quick keys', 'Under the vitals bar, above the command line: heal, recall, top 10, pack, score, flee, who, spells, tradeskills, commands, mail and milestones, all in one row. The first two are green and the same style as the rest; the compass keys (NW, N, NE, up and so on) are in the Movement window'], ['Windows menu', 'The <b>Windows</b> button next to the settings gear lists every window (Character, Enhancements, Quick buttons, Spells, Movement, Quests, Map, Room picture, Combat, Portrait, Gossip). Drag any window by its title bar to float it anywhere, drag its corner to resize it, close it with the X and tick it again in the menu to bring it back. <b>Reset window layout</b> puts everything back'], ['Map', 'Hover a room to see its name and click it to run there (rooms you have explored). The map is larger, and as a window you can make it larger still'], ['Settings Save', 'Settings save as you change them; the Save button confirms it and closes the panel'], ['Quest and team pop-ups', '<code>talk</code> and <code>board</code> open a quest window with Accept buttons (click Accept, or Accept all; Esc closes it). A team invitation opens a small window with Accept and Decline. Both can be dragged.'], ['ENHANCEMENTS', 'A box in the left column showing each active buff or effect with a bar that starts full and drains until it ends (red bars are harmful effects)'], ['Settings close button', 'The X in the corner of the settings panel closes it (so do the gear and Esc)'], ['Weather sounds', 'Rain and tornado loops and thunder play during weather (they follow the volume slider and the sound toggle, and stop with <code>mute weather on</code>)'], ['Settings: Mute announcements', 'Hide bounty announcements, player level-ups, quest completions or weather events'], ['Settings: Your title', 'Type a title and press Set; it shows on the who list'], ['Quick buttons', 'Under your weapon and armor: top 10, pack, score, flee, who, spells, tradeskills and commands. Each one runs that command for you'], ['Room picture', 'Under the map, a static picture of the room you are in. Rooms without their own picture show the default picture for their area (a crashed starship for Starship Aurora, a volcano for the Ember Wastes, and so on)'], ['The gear icon', 'The large gear at the top right of the screen opens the settings panel (Esc closes it)'], ['Settings: Theme', 'Seven looks: black, white, dark grey, dark blue, Old West, futuristic and fantasy'], ['Settings: Volume', 'A slider for every sound effect (level up, quest, death, login, legendary find and tradeskill level-up)'], ['<code>/g message</code>', 'Say something on the gossip channel']])}`);

  // ---------------- commands ----------------
  const CMDS = [
    ['Movement', [['n s e w u d ne nw se sw in out', 'Walk (or type the full word, e.g. north or northeast). <code>out</code> also leaves a room that has only one exit; the compass keys have NW, NE, SW, SE and out'], ['go &lt;dir&gt;', 'Walk by name'], ['runto &lt;room id&gt;', 'Run to a room you have explored in this area. Easier: <b>click a room on the map</b> (hover to see its name)'], ['speedwalk n,n,e,e,d', 'Walk a whole route in one command: directions n s e w u d, counts like <code>3n</code>, up to 60 steps. It stops if you cannot go that way or a fight starts; typing anything else cancels it (<code>speedwalk stop</code>). The <a href="directions.html">Directions</a> page has ready-made routes to every area'], ['recall', 'Return to the starting square (not while fighting)'], ['flee', 'Try to run from combat (about 65% success)']]],
    ['Looking', [['look [thing]', 'See the room, a monster or an item'], ['score (sc)', 'A graphical character sheet in a window: portrait, XP bar, health, mana, aura and luck, an attribute radar chart, attack and defense dice, equipment, wealth, quest progress and tradeskills. <code>score text</code> prints the text version'], ['check &lt;item&gt;', 'Shows a weapon\'s <b>weapon class</b> (damage range and average) or an armor\'s <b>armor class</b>, the slot, the level you need and how it compares with what you wear. Anything else answers "This isn\'t a piece of equipment."'], ['help &lt;command&gt;', 'Detailed help for any command, with usage, examples and related commands (aliases work: <code>help eq</code>). <code>help &lt;ability&gt;</code> explains a class ability'], ['inventory (inv, i, eq)', 'Shows every equipment slot (weapon, head, body, shield, feet) and what is worn in it, then your pack; kept items are marked [kept]'], ['finger &lt;name&gt;', 'A player\'s name, level, class, picture and email (if they set one). You can also click a name in the Who window'], ['email &lt;address&gt;', 'Add your email to your profile (also in settings). It is shown by finger unless you type <code>email hide</code>; <code>email clear</code> removes it'], ['brief on|off', 'With brief on, moving through rooms leaves out only the long room description: you still see the room name, exits, items, resources and who is here. <code>look</code> shows the long description too'], ['mail [player]', 'Mudmail: private mail to any player, even offline. <code>mail</code> opens your inbox (a window with Inbox, Compose and Forward tabs); <code>mail &lt;player&gt;</code> opens the compose window; <code>mail send &lt;player&gt; &lt;subject&gt; = &lt;message&gt;</code> sends from the command line; <code>mail read &lt;n&gt;</code>, <code>mail reply &lt;n&gt; = &lt;text&gt;</code>, <code>mail delete &lt;n|read|all&gt;</code>, <code>mail block &lt;player&gt;</code>'], ['mail forward on', 'Forward your mudmail to your personal email: set it with <code>email you@example.com</code>, type <code>mail forward on</code>, then confirm the 6-digit code you are emailed with <code>mail verify &lt;code&gt;</code>. <code>mail forward off</code> stops it. Finger shows who forwards'], ['phone <player> <message>', 'Your 🍍Phone Pro Max (always in your inventory, never in the bag, and it cannot be dropped, sold or salvaged) texts anyone online: <code>phone joe hello!</code> or <code>tell joe hello!</code>'], ['taxi', 'The Milestone Taxi: where it is, the route and how to ride (<code>enter taxi</code> at a stop, 30 credits per boarding; <code>out</code> to step out and touch a milestone)'], ['blackjack  /  bones <bet> <call>', 'Games in the saloons: blackjack (1,000 a hand) and Rolling Bones dice (see the Games page)'], ['value <item>', 'What a shop would pay for something you carry'], ['peace', 'Staff only (administrators and architects): ends every fight in the room and keeps monsters calm for two minutes'], ['prime', 'Unlocked at Remort 1 and yours forever: every 30 minutes, 5 minutes of +50% health, mana and luck (refilled), +50% spell power and half-price spells. The PRIME bar under your vitals counts down (click it to use PRIME)'], ['equip [list]', 'Looks through your pack and bag and puts on the best weapon and armor for each slot (only what your level allows); <code>equip list</code> previews'], ['events', 'The holiday calendar, what is on now and your turkey, bunny and reindeer kill counters'], ['trickortreat', 'Halloween week: knock on doors in town for candy, costumes and pranks'], ['fireworks', 'Fill the screen with fireworks for a few seconds'], ['launch', 'In the cockpit of the starship Tharsis: fly between Frostpeak Station and Mars'], ['changeclass [confirm <class>]', 'In the Hall of Many Faces (north of the Adventurers\' Guild) change your class for credits (free below level 5); gender changes are free'], ['deleteme [confirm]', 'Permanently delete your own character (asks you to confirm)'], ['suicide', 'Crisis lines and support information (also <code>help suicide</code>)'], ['visual combat', 'Settings has a Visual combat switch: a pop-up in the middle of the screen during fights; off shows combat messages in the main window'], ['elevator [floor]', 'Inside Meridian Tower (Modern district) each lobby has an elevator to the basement and floors 1 to 10; <code>elevator</code> opens the floor list with monster levels'], ['milestones', 'Every area has a standing stone, its milestone. <code>touch milestone</code> attunes you to it; <code>milestones</code> lists which you have touched'], ['milestone [area]', 'Standing at a milestone, open the travel window or type <code>milestone &lt;area&gt;</code> to jump to any milestone you have touched. You must be at a milestone to travel'], ['help aura / help builder', '<code>help aura</code> explains aura; <code>help builder</code> (also wizard, god) explains how to become an Architect and use the GUI area builder'], ['idea &lt;text&gt;', 'Sends a suggestion to the developer. It is filed in the <b>ideas</b> folder of the GitHub repository as a markdown file, and an issue is opened and assigned to toastmd. 8 to 1500 characters, one every 30 seconds'], ['bug &lt;text&gt;', 'Reports a bug the same way into the <b>bugs</b> folder (with your character, your room and the last lines of text you saw), assigned to toastmd. Say what you were doing and what you expected'], ['commands [category]', 'The list of commands you can use, grouped by category (add a category such as <code>social</code> for descriptions, or a word to search). It also lists your class abilities'], ['who', 'Everyone online, one per line: name (with any special pre-title), title, class, level and gender. Also opens the portrait window'], ['title &lt;text&gt;', 'Set your own title (up to 40 characters); <code>title clear</code> removes it'], ['mute [bounties|levels|quests|weather|taunts|deaths] [on|off]', 'Hide bounty announcements, level-ups, quest completions, weather, the <b>taunts</b> channel (NPCs taunting players who die) or the <b>deaths</b> channel (a line for every death), also in settings. <code>mute taunts on</code> hides it, <code>mute taunts off</code> shows it again'], ['deaths [n | player | top]', 'The death tally: recent player deaths with date, time, player and the NPC that killed them, plus the deadliest NPCs (it is saved between restarts)'], ['weather', 'What the weather is like in your area'], ['blackjack, hit, stand', 'Play blackjack at any saloon for 1000 credits a game: a win pays 1:1, blackjack pays 3:2, a tie returns your stake, and the dealer stands on 17'], ['equipment / inventory', 'What you wear and carry (plus tools and bag)'], ['class', 'Your class summary']]],
    ['Combat and magic', [['kill &lt;monster&gt;', 'Attack (also: attack, k). With <code>autokill on</code>, a bare <code>kill</code> attacks the first monster in the room'], ['autokill on|off', 'Toggle: when on, typing just <code>kill</code> (or <code>k</code>) attacks the first monster in the room. Saved with your character'], ['spells', 'List your abilities with level and mana cost'], ['cast &lt;spell&gt; [target]', 'Cast a spell (or just type the spell name)'], ['push', 'Spend Luck for +6 attack dice on your next two rounds'], ['luck', 'See your Luck points']]],
    ['Items and shopping', [['get &lt;item|all&gt;', 'Pick things up (loot goes to the bag)'], ['drop &lt;item&gt;', 'Drop an item (bound tools and the bag cannot be dropped)'], ['wield / wear / remove', 'Equip weapons and armor (level requirements apply)'], ['smoke [item]', 'Light a cigarillo to heal about 380 hit points. Old West bosses drop them'], ['upgrade [weapon] [confirm]', 'At a forge (Brann\'s Smithy) upgrade a weapon from +1 up to +10 for a lot of credits; each upgrade costs 1.75 times the last'], ['enter &lt;thing&gt;', 'Step into a portal or doorway, such as the mysterious portal at the Mirage Gate in the dunes'], ['quaff / eat [item]', 'Use a stim, cell or meal. With no item (<code>eat</code>, or the <b>heal</b> button) it picks the healing item that fits best, from your pack or bag'], ['list / buy [n] &lt;item&gt;', 'Shop (buy several with a number)'], ['sell &lt;item|all|materials&gt;', 'Sell to a shop (the bag too)'], ['keep &lt;item&gt;', 'Mark an item so it is never sold, rsold, salvaged or auctioned (worn items are already protected). <code>keep</code> alone lists them'], ['unkeep &lt;item|all&gt;', 'Make a kept item sellable and salvageable again'], ['value &lt;item&gt;', 'What a shop would pay'], ['pray', 'Heal at the Dawn Clinic'], ['rest', 'Heal fully at the inn']]],
    ['Bag of Holding and tools', [['bag', 'List your bag'], ['bag put &lt;item|all|materials|gear&gt;', 'Store items'], ['bag get &lt;item&gt; [n|all]', 'Take items out'], ['bag sell [materials]', 'Sell bag contents at a shop'], ['bag auto loot|overflow|off', 'Choose when things go into the bag'], ['tools', 'Your bound tools, their Mark and bonuses']]],
    ['Tradeskills', [['tradeskills [name]', 'List all tradeskills, or details and recipes'], ['learn &lt;skill&gt;', 'Learn one (free, any time)'], ['forage / mine / fish', 'Gather herbs, ore or fish where the room has them'], ['smith / brew / cook &lt;recipe&gt;', 'Craft (smithing needs a forge, cooking a hearth)'], ['salvage &lt;item|all&gt;', 'Break an unworn weapon or armor into materials. <code>salvage all</code> breaks down everything in your pack and bag that is not worn, not marked <code>keep</code> and not legendary']]],
    ['Quests', [['board', 'List contracts you can take'], ['talk &lt;npc&gt;', 'Speak to an NPC in the room. They greet you and hand in any finished contract, and a <b>pop-up window</b> shows everything they offer, with an <b>Accept</b> button on each quest and an <b>Accept all</b> button, so you never have to type <code>accept</code>'], ['accept &lt;quest&gt;', 'Accept a contract'], ['quests', 'Your accepted contracts and progress'], ['abandon &lt;quest&gt;', 'Drop a contract']]],
    ['Social', [['say &lt;text&gt;', 'Talk to the room (also: \' text)'], ['tell &lt;player&gt; &lt;text&gt;', 'Private message'], ['gossip &lt;text&gt;', 'Global channel (also /g in the browser); gossip on|off|history. Add <code>;word</code> for a GIPHY GIF: <code>gossip ;hi</code> or <code>gossip good game ;applause</code>. Paste a YouTube link to share a playable video with everyone'], ['shout &lt;text&gt;', 'Shout to everyone online'], ['leaderboard', 'The top 10 achievements: level, quests completed, tradeskills raised and bounty points (also the L key and the top 10 button)'], ['notify on|off', 'Hear (or mute) other players logging in and out']]],
    ['Character', [['autoheal on|off', 'Automatically eat or drink your best healing item (pack or bag) when your health drops to 40% or below; ignored if you have none'], ['autoflee on|off', 'Automatically try to flee when your health drops to 30% or below'], ['alias &lt;name&gt; &lt;commands&gt;', 'Make your own shortcut, e.g. <code>alias g get all</code>. Separate several commands with ;. Extra words are added to the last command. <code>alias</code> lists them'], ['unalias &lt;name&gt;', 'Remove an alias'], ['keypad [key command | on | off | reset]', 'See or change what the numeric keypad does'], ['notify on|off', 'Hear (or mute) login and logout notices'], ['rsell [list]', 'Remote sell: sells every unworn, non-legendary weapon and armor in your pack and bag from anywhere, minus a 10% finder\'s fee. <code>rsell list</code> previews the total'], ['auction &lt;item&gt; [opening bid]', 'Put equipment or treasure up for auction (anywhere). Bids go up in steps of 100 and nobody can bid more than their credits'], ['bid [amount]', 'Bid on the current auction (just <code>bid</code> raises by 100)'], ['auctions', 'Show the running auction and the queue (<code>auction off</code> mutes it, <code>auction cancel</code> withdraws yours before any bid)'], ['rob &lt;person&gt;, unlock vault, loot vault', 'Bank jobs in Dry Gulch: hold up stationary people, take the vault key from the Bank Manager, then open and loot the vault'], ['bounties', 'The wanted list: quest givers mark monsters as WANTED. Kill one for instant credits and bounty points, which count toward the leaderboard'], ['team [invite|accept|leave|kick|lead]', 'Form a team (up to 5). Kills split XP and credits among teammates in the same room, with +10% per extra member'], ['tc &lt;message&gt;', 'Team chat'], ['socials', 'List the feelings you can use, such as smile, cheer, dance, wave, bow, laugh, salute, hug (aim one at someone: <code>smile bob</code>)'], ['gag on|off', 'Hide (or show) every miss and fumble in combat'], ['trigger add &lt;text&gt; =&gt; &lt;command&gt;', 'Run a command automatically when matching text appears (also in settings). <code>triggers</code> lists them'], ['travel &lt;place&gt;', 'Walk to a landmark along safe rooms: guild, smithy, market, armory, temple, saloon, clinic, gate and forest (safe routes only)'], ['tutorial [off|reset]', 'Open (or turn off) the newbie tutorial with clickable steps'], ['gender [male|female|nonbinary]', 'View or change your gender'], ['remort', 'At level 40 in the Hall of Rebirth'], ['list / install / uninstall / cyber', 'Cyberware at the Chrome Clinic and Neural Implant Lab'], ['save / quit', 'Save and leave']]],
    ['Wizard only', [['update', 'Reload world, classes, quests and tradeskills from the files'], ['goto &lt;room&gt;', 'Teleport to a room id'], ['clone &lt;item&gt;', 'Create an item'], ['shutdown confirm|cancel', 'Save every player and stop the server after a 5 second countdown; <code>cancel</code> aborts it'], ['discord [test]', 'Status of the Discord gossip bridge, or send a test message'], ['github [sync]', 'Status of the GitHub sync, or push changes now']]],
  ];
  emit('commands', 'Commands', 'Everything you can type, grouped by what it does. Type <code>help</code> in the game for a short list.', CMDS.map(([g, rows]) => `${h2(g)}${table(['Command', 'What it does'], rows.map(([c, d]) => [`<code>${c}</code>`, d]))}`).join(''));

  // ---------------- FAQ ----------------
  const FAQ = [['Can I change my class?', 'Only by remorting at level 40, into Dragon, Android, Shapeshifter, Gambler, Ripperdoc, Outlaw or Pirate.'], ['What happens when I die?', 'You lose 10% of your XP, wake in Ashfall at half health, and a random NPC taunts you to the whole MUD. Nothing else is lost.'], ['How do I heal for free?', 'Type <code>pray</code> at the Dawn Clinic (free up to level 15), or <code>rest</code> at the inn. Camps and the inn also regenerate you faster.'], ['Why is my mana so low?', 'Chrome costs Aura, and your mana pool is scaled by your Aura out of 6. Uninstall a piece to get mana back. See <a href="cyberware.html">Cyberware</a>.'], ['Where do I sell materials?', 'Any shop buys them. The Salvage Exchange, east of the Ironbound Armory, pays 60% instead of 40%.'], ['What is Luck?', 'A small pool of points. One automatically halves a blow that would kill you, or <code>push</code> adds six attack dice. It refills on level-up and at the clinics.'], ['Can I drop or sell my bag or tools?', 'No. They are bound to you, load automatically, and are saved with your character. See <a href="tools-bag.html">Tools and Bag</a>.'], ['How does remort change levelling?', 'Each remort makes levelling 10% slower but gives +4% health and mana, +3% spell power, a bigger bag and a stronger class.'], ['How do I get around fast?', '<code>recall</code> returns you to Ashfall. The map shows exactly where you are.'], ['Do I need to learn tradeskills to gather?', 'Yes for foraging, mining and fishing (free: <code>learn mining</code>). Prospectors also gather with their class spells.'], ['Why can\'t I wear my gear after remorting?', 'You are level 1 again, and gear has level requirements. It waits in your pack.'], ['How do I mute login and logout messages?', 'Type <code>notify off</code>. Everyone online normally sees a notice when a player logs in or out.'], ['Is gossip shared with Discord?', 'If the server owner has set up the Discord bridge, gossip you type appears in the server\'s Discord channel, and messages from that channel appear in gossip as [Discord] name: text.'], ['How does the auction work?', 'Anyone can `auction` an unworn weapon, armor or treasure. Auctioneer Quincy Pike announces it and every bid. When bidding goes quiet he calls <b>going once</b>, waits 5 seconds, <b>going twice</b>, waits 5 more, then <b>SOLD</b>: the winner pays and receives the item, and the seller receives the credits. Any new bid restarts the count.'], ['How do I rob the bank?', 'Take the Bank Robbery contract from Slick Sam in the Rattlesnake Saloon, then walk east into the bank. <code>rob teller</code> holds up stationary people (guards come running if you fail). Kill Bank Manager Ebenezer Crane, pick up his brass key and use <code>unlock vault</code>, then <code>loot vault</code>. The vault holds a different sum each time. You can repeat the contract, but quest points are awarded only once.'], ['What is the Welcome to the Multiverse quest?', 'A quest you get automatically. Finish the newbie tutorial (press Finish on its last step) to earn quest points, credits, two stims and XP. It is rewarded once.'], ['Is there weather?', 'Yes, by area (with sounds: rain, thunder and a tornado roar). Old West areas get rain, dust devils and the occasional tornado. The Modern district gets rain and snow. Sci-fi areas get electrical storms and electromagnetic pulses. You see it as messages and as an animation over the room picture; indoors you only hear it muffled (an EMP reaches everywhere). It never hurts you, and <code>mute weather on</code> hides it.'], ['Who is killing everybody?', 'Type <code>deaths</code>. Every death is logged with the date, time, player and the NPC that killed them, and <code>deaths top</code> ranks the deadliest NPCs.'], ['How do I stop something being sold or salvaged?', 'Type <code>keep &lt;item&gt;</code>. Kept items show as [kept] in <code>inventory</code> and are skipped by <code>sell</code>, <code>sell all</code>, <code>rsell</code>, <code>salvage</code>, <code>salvage all</code> and the auction. <code>unkeep &lt;item&gt;</code> (or <code>unkeep all</code>) undoes it.'], ['How do I see someone\'s picture or email?', 'Type <code>finger &lt;name&gt;</code> or click their name in the Who window. Add your own email with <code>email you@example.com</code> or in settings; <code>email hide</code> keeps it private.'], ['Can I turn off long room descriptions?', 'Yes: <code>brief on</code> leaves out only the long description as you move (the room name, exits, items, resources and NPCs still show), <code>brief off</code> brings it back, and <code>look</code> always shows the full room.'], ['How do I accept a quest without typing?', 'Talk to the NPC (<code>talk torv</code>) or read the <code>board</code>: a pop-up lists the quests with an Accept button for each. A <code>team</code> invitation also opens a pop-up with Accept and Decline buttons.'], ['How do I send an idea or report a bug?', 'Type <code>idea &lt;your idea&gt;</code> or <code>bug &lt;what happened&gt;</code>. They go straight to the developer\'s GitHub as files in the ideas and bugs folders, with an issue assigned to toastmd.'], ['Where do Zeph and Rook go?', 'They train in the Proving Grounds, a fenced field behind the little gate in the Ashfall back alley (type <code>in</code> there). They stay there so the rest of the world is yours; visitors are welcome.'], ['How do I get to the dinosaurs?', 'Go to the Mirage Gate in the Sunscorch Dunes and <code>enter portal</code>. The Primeval Rift (levels 21 to 28) has raptors, pterosaurs, triceratops and Rex the Tyrant. Dr. Mara Quill\'s camp at the landing has quests and a shop; a portal there takes you home.'], ['Where are the vampires and demons?', 'Nightfall Hollow (levels 33 to 39): from the Shattered Citadel\'s Crypt Gate type <code>in</code>. Father Aldric\'s chapel is the safe place; vampires hold the manor to the north, werewolves the woods, witches the crossroads and demons the Brimstone Gate at the east end.'], ['How do I get an implant?', 'Go to the Chrome Clinic or the Neural Implant Lab in Ashfall (west of the saloon). <code>list</code> shows every implant with its price, aura cost, bonuses and level; <code>install &lt;name&gt;</code> buys and fits one (for example <code>install brawn implant mk i</code>). Each implant uses aura (you have 6.0), upgrades come in Marks that trade in the old one for half price, and <code>cyber</code> shows what you have. There is a sign on the lab wall (<code>read sign</code>) and <code>help implants</code> explains it all.'], ['How do I get things out of my bag?', '<code>look bag</code> lists it. <code>get sword from bag</code> or <code>bag get sword</code> takes one; <code>bag get all</code> takes every item (not materials) that fits in your pack, <code>bag get gear</code> all weapons and armor, <code>bag get materials</code> the materials. Gathered materials never count toward the bag capacity. With <code>bag auto loot</code> everything monsters drop goes straight in.'], ['How does the Milestone Taxi work?', 'A yellow taxi tours every milestone in turn and waits 30 seconds at each stop. When you see it idling in a milestone room, type <code>enter taxi</code> (30 credits). Ride on to the next stop for free, or type <code>out</code> to step out, touch the milestone, and board again for another 30 credits. <code>taxi</code> shows where it is.'], ['What are the holiday events?', 'Halloween, Thanksgiving, Easter, Christmas, New Year and the Fourth of July each run for 7 days around their date. Halloween: <code>trickortreat</code>. Thanksgiving: wild turkeys. Easter: bunnies and hidden painted eggs you can pick up and sell. Christmas: rogue reindeer that drop Santa hats and ugly sweaters. New Year: party hats and champagne in Ashfall Square. Fourth of July and New Year: fireworks (<code>fireworks</code>). Talk Like a Pirate Day (Sept 19, one day): everything you say, shout, gossip or text comes out in pirate. Pi Day (March 14, one day): pies to find and eat. Turkey, bunny and reindeer hunting each has a kill counter with rewards at 5, 10, 25, 50 and 100 (<code>events</code>).'], ['How do I get to Mars?', 'Go to Frostpeak Station (the Frostpeak area), then <code>in</code> to board the starship Tharsis, go north twice to the cockpit and type <code>launch</code>. Mars is for levels 30 and up. Commander Reyes waits at the landing pad.'], ['Where is the retirement home?', 'Golden Years Manor is at the end of Commerce Avenue in the Modern district (<code>in</code>). Its undead residents are level 12 to 18.'], ['How do I cast with a long name?', 'You do not have to: every ability is a one-word command with no underscores. Type the word (<code>rage</code>, <code>fireball</code>, <code>song</code>), with a target if needed. <code>spells</code> lists the words.'], ['What is the taunts channel?', 'When a player dies an NPC may taunt them, on the <b>taunts</b> channel (green). Every death is also announced on the <b>deaths</b> channel. Both can be switched off with <code>mute taunts on</code> and <code>mute deaths on</code>. Bots are never taunted.'], ['Where are the dinosaurs, the caveman and the CEO?', 'Dinosaurs: the Primeval Rift (enter the portal at the Mirage Gate). Caveman: the Mammoth Caverns, <code>in</code> from Stegosaur Valley in the Rift (Grog the Great waits in the deepest cavern). The CEO: Meridian Tower, north of Commerce Avenue in the Modern district, floor 10 (<code>elevator top</code>).'], ['How do I travel instantly?', 'Find the milestone (a standing stone, listed in the room) in each area, <code>touch milestone</code> to attune, and from any milestone use <code>milestone &lt;area&gt;</code> (or the Travel buttons in the window) to jump to any milestone you have touched. <code>milestones</code> shows where they all are.'], ['Can I get my mudmail by email?', 'Yes: put your email on your profile, <code>mail forward on</code>, and confirm the code you are sent. Mudmail then arrives in your inbox too, whether or not you are in the game.'], ['How do I become an Architect?', 'Type <code>help builder</code>: it explains the ranks (Player, Architect, Administrator), what you can build (any area is open for discussion), and how to apply. Architects use a point-and-click grid builder.'], ['What are bounties?', 'Every 15 minutes a quest giver marks a monster as WANTED and announces it to everyone. Type <code>bounties</code> to see where. The first player or team to kill it gets credits immediately plus bounty points, which add to the leaderboard score (x40 each).'], ['Can I change how the game looks?', 'Yes. Open settings (the gear) and pick a theme: black, white, dark grey, dark blue, Old West, futuristic or fantasy. The volume slider is there too.'], ['How do I get somewhere quickly?', 'Open the <a href="directions.html">Directions</a> page, copy the speedwalk line for your destination (for example <code>speedwalk 5e,s,u</code>) and paste it into the game. For town landmarks you can also type <code>travel guild</code>, <code>travel smithy</code> and so on.'], ['What can I type?', 'Type <code>commands</code> (or press the commands button) for every command by category and your class abilities.'], ['How do I get to the Modern district?', 'In Ashfall Square, type <code>up</code>: you step through the shimmering arch onto a modern strip with the Multi-Mart superstore, a shopping center, a trailer park, burgers, hot dogs, soda and gas stations with restrooms. The Directions page has routes to every shop and department.'], ['What is the tutorial?', 'New characters get a short dialog tour with clickable buttons for every first step. Click <b>Exit tutorial</b> to leave it, or type <code>tutorial</code> to reopen it.'], ['How do teams work?', 'Type <code>team invite &lt;player&gt;</code>; they type <code>team accept</code>. Credits and XP from each kill are split among teammates in the same room, with a 10% bonus for every extra member.'], ['Do the announcements go to Twitter?', 'If the server owner has set it up, legendary finds, boss kills, remorts and every 10th level are posted with #game and #Multiverse.'], ['Who are Zeph and Rook?', 'Resident bot players. They hunt, shop, chat and level like anyone else.'], ['How do I add my own areas?', 'The server owner can use the grid area builder at /builder.html.'], ['Is the sound free to use?', 'The three jingles are original and dedicated to the public domain (CC0).']];
  emit('faq', 'FAQ', 'Quick answers to the questions new players ask most.', FAQ.map(([q, a]) => `<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join(''));

  // ---------------- games ----------------
  emit('games', 'Games', 'Two card-and-dice games to play in the saloons: Blackjack and Rolling Bones.', `${h2('Where to play')}<p>Both games are played at the saloons: the <b>Silver Spur Saloon</b> in Ashfall, the Rattlesnake Saloon, the Lucky Strike, the Silver Dollar and the Brimstone Saloon Car. Look at the green-felt table in the room (<code>look table</code>) for a quick reminder of the rules. You cannot play while you are fighting.</p>
${h2('Blackjack')}<p>A hand of cards against the dealer. Get closer to 21 than the dealer without going over.</p>
${table(['Step', 'What happens'], [['1. Sit down', 'Type <code>blackjack</code>. The dealer takes <b>1,000 credits</b> and deals you two cards. The dealer gets two as well, but one stays face down.'], ['2. Count your cards', 'Number cards count their number. Jack, Queen and King are 10. An Ace is 11, or 1 if 11 would put you over 21.'], ['3. Hit or stand', '<code>hit</code> draws another card. <code>stand</code> keeps what you have. If you go over 21 you <b>bust</b> and lose your stake. At exactly 21 you stand automatically.'], ['4. The dealer plays', 'The dealer reveals the hidden card and draws until reaching 17 or more, then stands.'], ['5. Pay-out', 'Closer to 21 than the dealer (or the dealer busts): you win <b>1,000</b> on top of your stake. A natural 21 on the deal (Ace and a ten-card) pays <b>3 to 2</b>. A tie is a <b>push</b>: your 1,000 comes back. Otherwise you lose the 1,000.']])}
<p><b>Good to know:</b> walking out of the saloon in the middle of a hand forfeits your stake. <code>blackjack rules</code> repeats the rules in the game. Over time the house keeps about 6 credits of every 100 staked, so play for fun.</p>
${h2('Rolling Bones (dice)')}<p>A dice game for one. You call how two dice will land, bet from <b>10 to 1,000 credits</b>, and the bones decide. Type <code>bones &lt;bet&gt; &lt;call&gt;</code>, for example <code>bones 100 high</code> (<code>dice</code> works too, and <code>bones</code> alone lists the calls).</p>
${table(['Call', 'You win if...', 'Pays'], [['<code>low</code>', 'the total is 2 to 6', '1.25 to 1'], ['<code>high</code>', 'the total is 8 to 12', '1.25 to 1'], ['<code>seven</code>', 'the total is exactly 7', '4.5 to 1'], ['<code>doubles</code>', 'both dice show the same number', '4.5 to 1'], ['<code>snake</code>', 'snake eyes: a 1 and a 1', '30 to 1'], ['<code>boxcars</code>', 'boxcars: a 6 and a 6', '30 to 1']])}
<p>A win returns your bet plus the winnings; a miss costs the bet. Low and high both lose on a seven, which is the house's edge. The long shots (snake eyes and boxcars) pay the most, and they come up about once in 36 rolls.</p>
${h2('Examples')}${table(['You type', 'What happens'], [['<code>bones 100 high</code>', 'You bet 100. A roll of 4 and 5 (9) wins 125 credits, so you end with 225.'], ['<code>bones 50 seven</code>', 'You bet 50. A seven pays 225, so you end with 275. Any other total costs the 50.'], ['<code>blackjack</code>, then <code>hit</code>, <code>stand</code>', 'A full hand of blackjack for 1,000 credits.']])}`);
  // ---------------- classes ----------------
  const ctable = (keys) => table(['Class', 'Health/level', 'Mana/level', 'Regen', 'STR', 'DEX', 'CON', 'Starts with'], keys.map((k) => [`<b>${K[k].icon} ${K[k].name}</b>`, K[k].hpl, K[k].mpl, '+' + K[k].rg, K[k].str, K[k].dex, K[k].con, nm(K[k].kit)]));
  const ccard = (k) => card(`<div class="trio">${portraits(k)}</div>`, `${K[k].icon} ${K[k].name} ${pill(ROLE[k], K[k].remort ? 'c' : 'b')}`, `<p>${esc(K[k].desc)}</p><p class="m">${SP[k].length} abilities. First: ${SP[k].slice(0, 3).map((s) => esc(s.n)).join(', ')}. ${K[k].pwr ? 'Spell power ×' + K[k].pwr + '.' : ''} <a href="spells.html#${k}">All spells</a></p>`);
  emit('classes', 'Classes', 'Twelve classes to start, three more through remorting. Each has its own spells, health and mana, and playstyle.', `<p><b>The Juggernaut and the Titan have no spells at all.</b> They are all brawn: the biggest health pools in the game, a bonus to damage and attack, fast regeneration, and <b>quick heals</b> instead of spells (<code>secondwind</code>, <code>shrug</code>, <code>unbreakable</code>, and for the Titan <code>mountain</code>). Two passives make up for it: <b>Brute Force</b>, where any hit may randomly land a SMASH! for 50% to 100% extra damage, and <b>Thick Skin</b>, which shrugs off a share of every blow. The Titan is the remort version, and it grows stronger with every remort: more damage, more SMASH chance and thicker skin, plus a stun at Remort 10, life steal at Remort 30 and +25% damage at Remort 40. <code>help juggernaut</code> and <code>help titan</code> show the full sheets, and <code>help &lt;class&gt;</code> works for every class.</p>
<p>Class stat modifiers are added to your base attributes. <b>Health/level</b> and <b>mana/level</b> are what you gain per level. Regen is bonus mana every two seconds. The three portraits on each card show female, male and nonbinary versions of your generated character portrait.</p>
${h2('Starting classes')}${ctable(base)}<div class="cards">${base.map(ccard).join('')}</div>
${h2('Remort classes', 'remort')}<p>Unlocked only by <a href="remorting.html">remorting</a> at level 40. They have 40% stronger spells and start with more health.</p>${ctable(rem)}<div class="cards">${rem.map(ccard).join('')}</div>`);

  // ---------------- remorting ----------------
  const rrows = Array.from({ length: 40 }, (_, i) => i + 1).map((r) => [`Remort ${r}`, `+${4 * r}%`, `+${3 * r}%`, `+${Math.floor(r / 4)}`, `×${(1 + 0.1 * r).toFixed(1)}`, num(D.need(39) * (1 + 0.1 * r)), num(60 + 20 * r)]);
  emit('remorting', 'Remorting', 'At level 40 you can be reborn at level 1 as a stronger class, up to Remort 40.', `<p><b>PRIME:</b> the moment you reach Remort 1 you gain <b>PRIME</b>, which stays with you in perpetuity. Every 30 minutes you can type <code>prime</code> for 5 minutes of +50% health, mana and luck (all refilled), +50% spell power and half-price spells. The PRIME bar under your vitals shows the countdown.</p><p><b>New abilities:</b> every remort level unlocks one new, stronger one-word ability, added to your class's own list (Remort 1 gives <code>rekindle</code>, Remort 2 <code>afterimage</code>, and so on up to <code>godslayer</code> at Remort 40). They unlock at level 3 plus the remort number (capped at 40) and show in <code>spells</code> with a remort tag.</p>
<div class="banner2">${imgTag('banner-remorting.svg', 'Remort')}<p>Remorting is MULTIVERSE MUD's endgame loop. You reset to level 1, keep the things that cost real effort, and gain permanent bonuses and a remort class with more powerful skills.</p></div>
${h2('How to remort')}<ol class="plain"><li>Reach <b>level 40</b>.</li><li>Walk to the <b>Hall of Rebirth</b>: from the starting square, ${route('town/hall_of_rebirth')}.</li><li>Type <code>remort</code> to read the details, <code>remort dragon</code> (or android, shapeshifter) to preview, then <code>remort confirm dragon</code>.</li></ol>
${h2('What you keep and what resets')}${table(['You keep', 'You lose'], [['Name, gender and credits', 'Your level (back to 1) and XP'], ['Items (unequipped, in your pack and bag)', 'Your class (replaced by a remort class)'], ['Chrome and neural implants', 'Worn equipment (it goes into your pack; re-equip as you level)'], ['Quest points and completed contracts', 'Active buffs']])}
${h2('The remort classes')}<div class="cards">${rem.map((k) => card(`<div class="trio">${portraits(k)}</div>`, `${K[k].icon} ${K[k].name}`, `<p>${esc(K[k].desc)}</p><p class="m">${pill(ROLE[k], 'c')} <a href="spells.html#${k}">All spells</a></p>`)).join('')}</div>
${h2('Bonuses per remort')}<p>Each remort gives <b>+4% maximum health and mana</b>, <b>+3% spell power</b>, <b>+1 attack and defense die every 4 remorts</b>, and <b>+20 Bag of Holding slots</b>. Levelling gets <b>10% slower</b> each time, to keep progress meaningful.</p>${table(['Remort', 'Health and mana', 'Spell power', 'Extra dice', 'XP needed', 'Total XP for level 40', 'Bag slots'], rrows)}
<p>On the <code>who</code> list you appear as "Remort 3, L12 Dragon". Everyone online sees your rebirth announcement.</p>`);

  // ---------------- experience ----------------
  const need = (l) => D.need(l), xrows = Array.from({ length: 39 }, (_, i) => i + 1).map((l) => [l, num(need(l)), num(need(l) - (l > 1 ? need(l - 1) : 0)), `<span class="bar"><i style="width:${Math.round(need(l) / need(39) * 100)}%"></i></span>`]);
  const unlock = { 1: 'First spell', 2: 'Second spell', 4: 'Third spell; crypt becomes reasonable', 5: 'Scrap-tier gear', 6: 'Fourth spell', 8: 'Marsh', 10: 'Carbon-tier gear; level 10 spell', 12: 'Implant Mk II; Redrock Trail and mines', 15: 'Fifth-tier spell; free healing ends', 16: 'Nano-weave gear', 18: 'Dunes', 22: 'Runed gear', 24: 'Frostpeak', 28: 'Smartsteel gear', 30: 'Ember Wastes', 33: 'Dragonscale gear', 35: 'Citadel', 36: 'Implant Mk IV', 38: 'Voidforged gear (drop only)', 39: 'The Abyss', 40: 'Final spell; remort available' };
  emit('experience', 'Experience and Levels', 'How much XP each level takes, what unlocks when, and how remorting changes it.', `
<p>You gain XP from monsters and contracts. To leave level <i>L</i> you need a total of <b>50 × L²</b> experience, so each level costs a little more than the last. At level 40 you stop levelling and can <a href="remorting.html">remort</a>. <code>score</code> tells you exactly how many XP you still need.</p>
${h2('Milestones')}${table(['Level', 'What happens'], Object.entries(unlock).map(([l, t]) => [l, t]))}
${h2('XP table, levels 1 to 39')}${table(['Level', 'Total XP to reach the next level', 'Gap from the previous level', 'Relative'], xrows, { filter: 'xp' })}
${h2('Remort changes the price')}<p>The totals above are multiplied by 1 + 0.1 × your remort number. At Remort 5 that is ×1.5, at Remort 10 ×2, at Remort 40 ×5. See the <a href="remorting.html">remort table</a> for the full list.</p>
${h2('Where to earn XP')}${table(['Area', 'Typical level', 'XP per kill (normal monster)'], ['forest', 'crypt', 'marsh', 'road', 'mines', 'dunes', 'frost', 'ember', 'citadel', 'abyss'].map((a) => { const ms = L.CATALOG.filter((r) => r.area === a).flatMap((r) => r.def.mobs || []).map((id) => D.W.mobs[id]).filter((m) => m && !m.boss); const lv = ms.map((m) => m.level), xp = ms.map((m) => m.xp); return [`<a href="areas.html#${a}">${L.AREAS[a][0]}</a>`, `${Math.min(...lv)} to ${Math.max(...lv)}`, `${num(Math.min(...xp))} to ${num(Math.max(...xp))}`]; }))}`);

  // ---------------- attributes and combat ----------------
  emit('combat', 'Attributes and Combat', 'MULTIVERSE MUD fights with pools of six-sided dice. Here is how attacks, defense, Luck and Aura work.', `
${h2('Dice pools')}<p>Every attack and defense is a roll of several six-sided dice. A <b>5 or 6 is a hit</b>. An attack lands when the attacker's hits beat the defender's hits; the surplus ("net hits") adds <b>6% damage each</b> (up to 8). <b>Six or more net hits is a critical</b> (×1.4). If more than half the dice show 1 and there are no hits, the attack is a <b>fumble</b>.</p>
${table(['Pool', 'Formula'], [['Attack dice', '5 + level÷2 + Reflex÷4 + buffs + chrome + remort÷4'], ['Defense dice', '2 + level÷4 + Reflex÷6 + armor÷5 + evasion buffs + remort÷4'], ['Damage', 'weapon roll + Brawn÷5 + buffs + chrome, then net-hit bonus, then minus a random slice of the target\'s armor']])}
<p>Spells do not roll to hit. Instead the target <b>resists</b> with a dice pool, shaving up to 25% off the damage.</p>
${h2('Attributes')}${table(['Attribute', 'Raises', 'Source'], [['Brawn', 'Damage and carrying strength', '10 + 0.8 per level + class + chrome'], ['Reflex', 'Attack and defense dice', '10 + 0.5 per level + class + chrome'], ['Grit', 'Health', '10 + 0.7 per level + class + chrome'], ['Mind', 'Mana (4 per point from implants)', 'Level, class, neural implants'], ['Will', 'Luck (implants)', 'Level, class, neural implants'], ['Charm', 'Loot credits (+2% per point from implants)', 'Level, class, neural implants']])}
${h2('Health and mana')}<p><b>Health</b> = (30 + level × class health + Grit × 2 + chrome) × (1 + 4% per remort). <b>Mana</b> = (15 + level × class mana + chrome + Mind × 4) × <b>Aura ÷ 6</b> × (1 + 4% per remort). Spell power grows 12% per level past 10, ×1.4 for remort classes, +3% per remort.</p>
${h2('Luck')}<p>You hold 3 Luck points (+1 per 10 levels, +1 per 2 Will from implants). A point is spent <b>automatically</b> to halve a blow that would kill you, or on purpose with <code>push</code> for +6 attack dice for two rounds. Luck refills on level-up, with <code>pray</code> and <code>rest</code>, and slowly over time.</p>
${h2('Aura')}<p>Aura is your integrity, 6.0 at most. Every piece of <a href="cyberware.html">chrome</a> costs some. Your mana pool is scaled by Aura ÷ 6, so heavy chrome starves casters.</p>
${h2('Status effects')}${table(['Effect', 'What it does'], [['Stun', 'The target skips its turns'], ['Poison, burn, curses (damage over time)', 'Hurt every two seconds for several rounds'], ['Buffs', 'More armor, damage, critical dice, evasion or regeneration for a time'], ['Summons', 'An ally strikes your enemy every round']])}
${h2('Death')}<p>You lose 10% of your XP and wake in Ashfall at half health. A random NPC taunts you by name to everyone online. Nothing is dropped.</p>`);

  // ---------------- cyberware and implants ----------------
  const cy = Object.entries(D.W.items).filter(([, i]) => i.type === 'cyber'), bon = (b) => Object.entries(b).map(([k, v]) => `+${v} ${k}`).join(', ');
  const clinic = cy.filter(([, i]) => !i.line), imps = cy.filter(([, i]) => i.line), shopOf = (id) => ROOM[Object.keys(ROOM).find((p) => ROOM[p].def.clinic && ROOM[p].def.clinic.stock.includes(id))];
  writeImg('icon-chrome.svg', art.icon('chrome'));
  emit('cyberware', 'Cyberware and Implants', 'Chrome makes you stronger and costs Aura. Neural implants are a rare, expensive series of small stat boosts.', `
<div class="banner2">${imgTag('icon-chrome.svg', 'Chrome')}<p>Two clinics sell augmentations. Each piece costs <b>Aura</b> (you have 6.0). Less Aura means a smaller mana pool, so chrome is a trade-off, especially for casters.</p></div>
${h2('Chrome Clinic')}<p>West of the inn (${route('town/clinic')} from the square). <code>list</code>, <code>install &lt;name&gt;</code>, <code>uninstall &lt;name&gt;</code> (50% refund), <code>cyber</code>.</p>${table(['Cyberware', 'Level', 'Price', 'Aura cost', 'Effect'], clinic.map(([, i]) => [`<b>${i.name}</b>`, i.lvl, num(i.value) + 'c', i.aura, bon(i.bonus)]))}
${h2('Neural Implant Lab: the implant series')}<p>West of the clinic (${route('town/implant_lab')}). Six attributes, five Marks each. <b>Install in order</b>: Mk I first, then Mk II, and so on. Each upgrade trades the old Mark in for half its price. They are expensive and boost stats <i>a little</i>.</p>${table(['Implant', 'Level', 'Price', 'Aura cost', 'Effect'], imps.map(([, i]) => [`<b>${i.name}</b>`, i.lvl, num(i.value) + 'c', i.aura, bon(i.bonus)]), { filter: 'imps' })}
${h2('What each attribute does')}<p><b>Brawn</b> adds damage, <b>Reflex</b> adds attack and defense dice, <b>Grit</b> adds health, <b>Mind</b> adds 4 mana per point, <b>Will</b> adds Luck (1 per 2 points), and <b>Charm</b> adds 2% loot credits per point.</p>`);
};
